const defaultSidebarSections: SidebarSection[] = [
  {
    id: "main",
    items: [
      { id: "toko", label: "Toko", icon: <HomeIcon />, href: "/store" },
      { id: "paket", label: "Paket", icon: <CrownIcon />, href: "/bundle" },
      { id: "perpustakaan", label: "Perpustakaan", icon: <GamesIcon />, href: "/library" },
      { id: "riwayat", label: "Riwayat Pembelian", icon: <ClockIcon /> },
    ],
  },
  {
    id: "explore",
    items: [
      { id: "request", label: "Request Game", icon: <AddIcon />, href: "/request" },
      { id: "wishlist", label: "Wishlist", icon: <BookmarkIcon />, href: "/wishlist" },
      { id: "leaderboard", label: "Leaderboard", icon: <LeaderboardIcon />, href: "/leaderboard" },
      { id: "ulasan", label: "Ulasan", icon: <ReviewIcon /> },
    ],
  },
  {
    id: "other",
    items: [
      { id: "artikel", label: "Artikel", icon: <ArticleIcon /> },
      { id: "pengaturan", label: "Pengaturan", icon: <SettingsIcon /> },
    ],
  },
];

export function Sidebar({
  sections = defaultSidebarSections,
  activeId,
  onItemClick,
  headerSlot,
  footerSlot,
  className,
  ref,
  ...props
}: SidebarProps) {
  return (
    <aside
      ref={ref}
      className={cn(
        "flex flex-col bg-deep-blue-950 border-r border-r-gradient-secondary px-10 py-6 w-fit min-w-65 select-none",
        className
      )}
      {...props}
    >
      {/* 1. Header Slot Opsional */}
      {headerSlot && (
        <div className="pb-6 border-b border-b-gradient-secondary mb-6">
          {headerSlot}
        </div>
      )}

      {/* 2. Navigation Sections */}
      <nav className="flex flex-col">
        {sections.map((section, sectionIdx) => (
          <div key={section.id || sectionIdx} className="flex flex-col">
            {/* Section Item List */}
            <div className="flex flex-col gap-3">
              {section.items.map((item) => {
                const isActive = activeId === item.id;
                const itemClasses = cn(
                  "flex items-center gap-4 text-left transition-colors duration-150 group cursor-pointer outline-none focus-visible:ring-1 focus-visible:ring-gray-50/50 rounded-md py-1",
                  item.disabled && "opacity-50 pointer-events-none cursor-not-allowed",
                  isActive && "font-bold"
                );

                const itemContent = (
                  <>
                    {/* Icon Slot */}
                    <span
                      className={cn(
                        "text-deep-blue-100 flex items-center justify-center shrink-0 w-4 h-4 [&>svg]:w-4 [&>svg]:h-4 transition-colors duration-150 group-hover:text-gray-50",
                        isActive && "text-gray-50"
                      )}
                    >
                      {item.icon}
                    </span>

                    {/* Label Slot */}
                    <span
                      className={cn(
                        "text-gray-50 text-label-sm font-semibold transition-colors duration-150 group-hover:text-gray-50 tracking-normal",
                        isActive && "text-gray-50 font-bold"
                      )}
                    >
                      {item.label}
                    </span>

                    {/* Badge Slot */}
                    {item.badge && (
                      <span className="ml-auto flex items-center">
                        {item.badge}
                      </span>
                    )}
                  </>
                );

                return item.href ? (
                  <Link
                    key={item.id}
                    href={item.href}
                    onClick={() => onItemClick?.(item)}
                    className={itemClasses}
                  >
                    {itemContent}
                  </Link>
                ) : (
                  <button
                    key={item.id}
                    type="button"
                    disabled={item.disabled}
                    onClick={() => onItemClick?.(item)}
                    className={itemClasses}
                  >
                    {itemContent}
                  </button>
                );
              })}
            </div>

            {/* Linear Border Divider Between Sections (py-6 spacing) */}
            {sectionIdx < sections.length - 1 && (
              <div className="py-6">
                <div className="border-b-gradient-secondary w-full" />
              </div>
            )}
          </div>
        ))}
      </nav>

      {/* 3. Footer Slot Opsional */}
      {footerSlot && (
        <div className="mt-auto pt-6 border-t border-b-gradient-secondary">
          {footerSlot}
        </div>
      )}
    </aside>
  );
}
